  get(t, key, receiver) {
    seen.push(String(key));
    return Reflect.get(t, key, receiver);
  },
  set(t, key, value, receiver) {
    if (key === "_count" && (!Number.isInteger(value) || value < 0)) {
      throw new RangeError("_count must be a non-negative integer");
    }
    return Reflect.set(t, key, value, receiver);
