function animateX(element, pixels, duration, {
  request = requestAnimationFrame,
  cancel = cancelAnimationFrame
} = {}) {
  if (!Number.isFinite(pixels) || !Number.isFinite(duration) || duration < 0) {
    throw new RangeError("invalid animation parameters");
  }
  let id = null, start = null, stopped = false;
  function frame(now) {
    if (stopped) return;
    if (start === null) start = now;
    const progress = duration === 0 ? 1 : Math.min(1, (now - start) / duration);
    element.style.transform = `translateX(${pixels * progress}px)`;
    id = progress < 1 ? request(frame) : null;
  }
  id = request(frame);
  return () => { stopped = true; if (id !== null) cancel(id); };
}

// 确定性测试：无需 DOM 或真实时钟，可在现代 Node.js 中运行。
function assert(ok, message) { if (!ok) throw new Error(message); }
function fakeFrames() {
  let nextId = 0;
  const jobs = new Map();
  return {
    request(fn) { const id = nextId++; jobs.set(id, fn); return id; },
    cancel(id) { jobs.delete(id); },
    tick(time) {
      const pending = [...jobs.entries()];
      for (const [id, fn] of pending) {
        if (jobs.delete(id)) fn(time);
      }
    },
    get size() { return jobs.size; }
  };
}
const clock = fakeFrames(), box = { style: {} };
animateX(box, 100, 1000, clock);
clock.tick(20);
