function updateComment(items, event) {
  const index = items.findIndex(x => x.clientId === event.clientId);
  if (event.type === 'pending') {
    return index < 0 ? [...items, { clientId: event.clientId, text: event.text, pending: true }] : items;
  }
  if (event.type === 'failed') {
    return items.filter(x => x.clientId !== event.clientId || !x.pending);
  }
  if (event.type === 'confirmed') {
    const item = { ...event.comment, clientId: event.clientId, pending: false };
    return index < 0 ? [...items, item] : items.map((x, i) => i === index ? item : x);
  }
  return items;
}

// 与上面的函数放在同一 demo.js，可用现代 Node.js 运行。
function assert(ok, label) { if (!ok) throw new Error(label); }
const base = Object.freeze([
  Object.freeze({ clientId: 'existing', id: 1, text: 'old', pending: false })
]);
const pendingEvent = { type: 'pending', clientId: 'a', text: 'draft' };
const a = updateComment(base, pendingEvent);
assert(base.length === 1 && a.length === 2, 'immutable append');
assert(updateComment(a, pendingEvent) === a, 'pending replay reuses state');
const b = updateComment(a, { type: 'pending', clientId: 'b', text: 'second' });
