  type: 'confirmed', clientId: 'a', comment: { id: 2, text: 'normalized' }
});
assert(confirmed.length === 3 && confirmed[1].id === 2 &&
  confirmed[1].text === 'normalized' && !confirmed[1].pending, 'confirmation replaces');
assert(a[1].pending && a[1].text === 'draft', 'previous state unchanged');
const lateFailure = updateComment(confirmed, { type: 'failed', clientId: 'a' });
assert(lateFailure.some(x => x.clientId === 'a' && x.id === 2), 'confirmed survives failure');
const failed = updateComment(lateFailure, { type: 'failed', clientId: 'b' });
assert(failed.length === 2 && !failed.some(x => x.clientId === 'b'), 'only own pending removed');
const missingFail = updateComment(failed, { type: 'failed', clientId: 'missing' });
assert(JSON.stringify(missingFail) === JSON.stringify(failed), 'unknown failure preserves contents');
assert(updateComment(failed, { type: 'unknown', clientId: 'a' }) === failed, 'unknown event ignored');
const directConfirm = updateComment([], {
  type: 'confirmed', clientId: 'c', comment: { id: 3, text: 'server' }
});
assert(directConfirm.length === 1 && !directConfirm[0].pending, 'confirmation may arrive first');
const retry = updateComment(failed, { type: 'pending', clientId: 'b', text: 'retry' });
assert(retry.filter(x => x.clientId === 'b').length === 1, 'removed operation may retry');
assert(updateComment(confirmed, {
  type: 'confirmed', clientId: 'a', comment: { id: 2, text: 'normalized' }
