import { useEffect, useEffectEvent } from 'react';

function ChatRoom({ roomId, theme }) {
  const onConnected = useEffectEvent(() => {
    showNotification('已连接', theme);
  });
  useEffect(() => {
    let active = true;
    const connection = createConnection(roomId);
    connection.on('connected', () => {
      if (active) onConnected();
    });
    connection.connect();
    return () => {
      active = false;
      connection.disconnect();
    };
  }, [roomId]);
  return null;
}

import { useState } from 'react';

function useCounter(initial = 0) {
  const [count, setCount] = useState(initial);
  return {
    count,
    increment: () => setCount(n => n + 1),
    reset: () => setCount(initial),
  };
}
function CounterCard({ label }) {
  const counter = useCounter();
  return <button onClick={counter.increment}>
    {label}: {counter.count}
  </button>;
}
export default function Counters() {
  return <><CounterCard label="A" /><CounterCard label="B" /></>;
}

function reducer(state, action) {
  switch (action.type) {
    case 'INCREMENT':
    case 'DECREMENT': {
      const delta = action.type === 'INCREMENT' ? state.step : -state.step;
      return { ...state, count: state.count + delta,
        history: [...state.history, state.count] };
    }
    case 'SET_STEP':
      return Number.isFinite(action.step) && action.step > 0
        ? { ...state, step: action.step } : state;
    case 'RESET':
      return { ...state, count: 0, history: [] };
    case 'UNDO': {
      if (state.history.length === 0) return state;
      return { ...state, count: state.history[state.history.length - 1],
        history: state.history.slice(0, -1) };
    }
    default:
      throw new Error('Unknown action: ' + action.type);
  }
}
// 组件内：useReducer(reducer, { count: 0, step: 1, history: [] });

function checkBudget(previous, current, maxBytes, maxGrowth) {
  const values = [previous, current, maxBytes, maxGrowth];
  if (values.some(x => typeof x !== 'number' || !Number.isFinite(x) || x < 0)) {
    throw new TypeError('Expected finite non-negative numbers');
  }
  const growth = previous === 0 ? null : (current - previous) / previous;
  const reasons = [];
  if (current > maxBytes) reasons.push('absolute');
  if (growth !== null && growth > maxGrowth) reasons.push('growth');
  return { pass: reasons.length === 0, growth, reasons };
}

function debounce(fn, wait = 0) {
  let timer;
  function wrapped(...args) {
    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = undefined;
      fn.apply(this, args);
    }, wait);
  }
  wrapped.cancel = () => {
    clearTimeout(timer);
    timer = undefined;
  };
  return wrapped;
}

async function pool(tasks, limit) {
  if (!Number.isInteger(limit) || limit < 1)
    throw new RangeError('limit must be positive');
  const results = new Array(tasks.length);
  let next = 0;
  async function worker() {
    while (next < tasks.length) {
      const i = next++;
      try {
        results[i] = { status: 'fulfilled',
          value: await tasks[i]() };
      } catch (reason) {
        results[i] = { status: 'rejected', reason };
      }
    }
  }
  await Promise.all(Array.from(
    { length: Math.min(limit, tasks.length) }, worker));
  return results;
}

function flatten(input) {
  const stack = [];
  const out = [];
  for (let i = input.length - 1; i >= 0; i--)
    stack.push(input[i]);
  while (stack.length) {
    const value = stack.pop();
    if (Array.isArray(value)) {
      for (let i = value.length - 1; i >= 0; i--)
        stack.push(value[i]);
    } else {
      out.push(value);
    }
  }
  return out;
}

class LRU {
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity < 1)
      throw new RangeError('invalid capacity');
    this.capacity = capacity;
    this.map = new Map();
  }
  has(key) { return this.map.has(key); }
  get(key) {
    if (!this.map.has(key)) return undefined;
    const value = this.map.get(key);
    this.map.delete(key);
    this.map.set(key, value);
    return value;
  }
  set(key, value) {
    this.map.delete(key);
    this.map.set(key, value);
    if (this.map.size > this.capacity)
      this.map.delete(this.map.keys().next().value);
  }
}

const cache = new LRU(2);
cache.set('a', undefined);
cache.set('b', 2);
if (!cache.has('a')) throw Error('missing a');
cache.get('a');
cache.set('c', 3);
if (cache.has('b') || !cache.has('a'))
  throw Error('wrong eviction');

function throttle(fn, wait) {
  let timer = null, pending = null;
  function fire(ctx, args) {
    timer = setTimeout(tick, wait);
    fn.apply(ctx, args);
  }
  function tick() {
    timer = null;
    if (!pending) return;
    const [ctx, args] = pending;
    pending = null;
    fire(ctx, args);
  }
  function wrapped(...args) {
    if (timer === null) fire(this, args);
    else pending = [this, args];
  }
  wrapped.cancel = () => {
    clearTimeout(timer);
    timer = null;
    pending = null;
  };
  return wrapped;
}

class Emitter {
  events = new Map();
  on(name, fn) {
    let set = this.events.get(name);
    if (!set) this.events.set(name, set = new Set());
    set.add(fn);
    return () => {
      set.delete(fn);
      if (!set.size && this.events.get(name) === set)
        this.events.delete(name);
    };
  }
  once(name, fn) {
    let fired = false;
    const off = this.on(name, (...args) => {
      if (fired) return;
      fired = true;
      off();
      fn(...args);
    });
    return off;
  }
  emit(name, ...args) {
    for (const fn of [...(this.events.get(name) || [])])
      fn(...args);
  }
}

function allValues(iterable) {
  return new Promise((resolve, reject) => {
    const out = [];
    let remaining = 1, index = 0;
    for (const item of iterable) {
      const i = index++;
      remaining++;
      Promise.resolve(item).then(value => {
        out[i] = value;
        if (--remaining === 0) resolve(out);
      }, reject);
    }
    if (--remaining === 0) resolve(out);
  });
}

function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(signal.reason);
    const abort = () => {
      clearTimeout(id);
      reject(signal.reason);
    };
    const id = setTimeout(() => {
      signal?.removeEventListener('abort', abort);
      resolve();
    }, ms);
    signal?.addEventListener('abort', abort, { once: true });
  });
}
async function retry(task, { attempts = 3, delay = 100,
  maxDelay = 30000, signal, shouldRetry = () => true } = {}) {
  if (!Number.isSafeInteger(attempts) || attempts < 1)
    throw new RangeError('invalid attempts');
  if (![delay, maxDelay].every(x => typeof x === 'number'
      && Number.isFinite(x) && x >= 0)
      || maxDelay > 2147483647)
    throw new RangeError('invalid delay');
  let pause = Math.min(delay, maxDelay);
  for (let i = 0; i < attempts; i++) {
    signal?.throwIfAborted();
    try {
      const value = await task(signal);
      signal?.throwIfAborted();
      return value;
    } catch (error) {
      signal?.throwIfAborted();
      if (i + 1 === attempts || !shouldRetry(error))
        throw error;
      await sleep(pause, signal);
      pause = Math.min(pause * 2, maxDelay);
    }
  }
}

function clonePlain(value, seen = new WeakMap()) {
  if (value === null || typeof value !== 'object') {
    if (typeof value === 'function') throw new TypeError();
    return value;
  }
  if (seen.has(value)) return seen.get(value);
  const proto = Object.getPrototypeOf(value);
  if (!Array.isArray(value) && proto !== Object.prototype
      && proto !== null) throw new TypeError('unsupported');
  const out = Array.isArray(value)
    ? new Array(value.length) : Object.create(proto);
  seen.set(value, out);
  for (const key of Reflect.ownKeys(value)) {
    const d = Object.getOwnPropertyDescriptor(value, key);
    if (!d.enumerable) continue;
    if (!('value' in d)) throw new TypeError('accessor');
    Object.defineProperty(out, key, {
      value: clonePlain(d.value, seen), enumerable: true,
      writable: true, configurable: true
    });
  }
  return out;
}

function toForest(rows) {
  const nodes = new Map(), roots = [];
  for (const r of rows) {
    if (typeof r.id !== 'string' || !r.id || nodes.has(r.id))
      throw new Error('invalid or duplicate id');
    nodes.set(r.id, { id: r.id, parentId: r.parentId,
      name: r.name, children: [] });
  }
  for (const node of nodes.values()) {
    if (node.parentId === null) roots.push(node);
    else {
      const parent = nodes.get(node.parentId);
      if (!parent) throw new Error('orphan');
      parent.children.push(node);
    }
  }
  const stack = [...roots];
  let count = 0;
  while (stack.length) {
    const node = stack.pop();
    count++;
    for (const child of node.children) stack.push(child);
  }
  if (count !== nodes.size) throw new Error('cycle');
  return roots;
}

function shortestPath(graph, start, goal) {
  const prev = new Map([[start, null]]);
  const queue = [start];
  for (let head = 0; head < queue.length; head++) {
    const node = queue[head];
    if (node === goal) {
      const path = [];
      for (let x = node; x !== null; x = prev.get(x))
        path.push(x);
      return path.reverse();
    }
    for (const next of graph.get(node) || []) {
      if (!prev.has(next)) {
        prev.set(next, node);
        queue.push(next);
      }
    }
  }
  return null;
}

function lowerBound(a, target) {
  let lo = 0, hi = a.length;
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (a[mid] < target) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

function mergeIntervals(input) {
  const a = input.map(([s, e]) => {
    if (!Number.isFinite(s) || !Number.isFinite(e) || s > e)
      throw new TypeError('invalid interval');
    return [s, e];
  }).sort((x, y) => x[0] - y[0]);
  const out = [];
  for (const [s, e] of a) {
    const last = out[out.length - 1];
    if (last && s <= last[1]) last[1] = Math.max(last[1], e);
    else out.push([s, e]);
  }
  return out;
}

function parseQuery(query) {
  const out = new Map();
  for (const [key, value] of new URLSearchParams(query)) {
    if (!out.has(key)) out.set(key, []);
    out.get(key).push(value);
  }
  return out;
}

function singleFlight(loader) {
  const inflight = new Map();
  return function load(key) {
    if (inflight.has(key)) return inflight.get(key);
    const clear = () => {
      if (inflight.get(key) === p) inflight.delete(key);
    };
    const p = Promise.resolve().then(() => loader(key)).then(
      value => { clear(); return value; },
      error => { clear(); throw error; }
    );
    inflight.set(key, p);
    return p;
  };
}

function latestOnly(load, commit) {
  let generation = 0, controller;
  const run = async input => {
    const id = ++generation;
    const previous = controller;
    const current = controller = new AbortController();
    previous?.abort();
    if (id !== generation || current.signal.aborted) return;
    try {
      const value = await load(input, current.signal);
      if (id === generation && !current.signal.aborted) {
        commit(value);
        return value;
      }
    } catch (error) {
      if (id === generation && !current.signal.aborted)
        throw error;
    }
  };
  run.cancel = () => { generation++; controller?.abort(); };
  return run;
}

function sortRows(rows) {
  const collator = new Intl.Collator('zh-CN');
  return [...rows].sort((a, b) => {
    const am = a.score === null, bm = b.score === null;
    if (am !== bm) return am ? 1 : -1;
    if (!am && a.score !== b.score) return b.score - a.score;
    return collator.compare(a.name, b.name);
  });
}

function history(initial, limit = 50) {
  if (!Number.isInteger(limit) || limit < 1)
    throw new RangeError('invalid limit');
  let present = initial, past = [], future = [];
  return {
    get value() { return present; },
    commit(next) {
      past.push(present);
      if (past.length > limit) past.shift();
      present = next; future = [];
    },
    undo() {
      if (!past.length) return false;
      future.push(present); present = past.pop();
      return true;
    },
    redo() {
      if (!future.length) return false;
      past.push(present); present = future.pop();
      return true;
    }
  };
}

function windowRange(count, rowHeight, height,
                     scrollTop, overscan = 2) {
  const total = count * rowHeight;
  const top = Math.max(0, Math.min(scrollTop,
    Math.max(0, total - height)));
  const start = Math.max(0,
    Math.floor(top / rowHeight) - overscan);
  const end = Math.min(count,
    Math.ceil((top + height) / rowHeight) + overscan);
  return { start, end, offset: start * rowHeight, total };
}

function createLatestGate() {
  let epoch = 0;
  let controller = null;
  return {
    begin() {
      const previous = controller;
      const own = new AbortController();
      const id = ++epoch;
      controller = own;
      previous?.abort();
      return {
        signal: own.signal,
        commit(write) {
          if (id !== epoch || own.signal.aborted) return false;
          write();
          return true;
        }
      };
    },
    cancel() {
      const previous = controller;
      controller = null;
      epoch++;
      previous?.abort();
    }
  };
}

function safeCitation(raw, allowedOrigins, base = 'https://kb.example/') {
  if (typeof raw !== 'string' || /[\u0000-\u0020\u007f]/.test(raw)) return null;
  try {
    const url = new URL(raw, base);
    if (url.protocol !== 'https:' || url.username || url.password) return null;
    if (!allowedOrigins.has(url.origin)) return null;
    return url.href;
  } catch {
    return null;
  }
}

function createRunBuffer(runId, maxChars = 100000) {
  if (!Number.isSafeInteger(maxChars) || maxChars < 0) throw new TypeError('Invalid limit');
  const chunks = [];
  let lastSeq = 0, size = 0, status = 'streaming';
  return {
    push(e) {
      if (e.runId !== runId || status !== 'streaming') return false;
      if (!Number.isSafeInteger(e.seq) || e.seq < 1) throw new TypeError('Invalid sequence');
      if (e.seq <= lastSeq) return false;
      if (e.seq !== lastSeq + 1) throw new Error('Sequence gap: resync required');
      if (e.type === 'delta') {
        if (typeof e.text !== 'string') throw new TypeError('Invalid delta');
        if (size + e.text.length > maxChars) throw new RangeError('Buffer limit');
        if (e.text.length > 0) chunks.push(e.text);
        size += e.text.length;
      } else if (e.type === 'done') {
        status = 'done';
      } else {
        throw new TypeError('Unknown event');
      }
      lastSeq = e.seq;
      return true;
    },
    read() { return { text: chunks.join(''), lastSeq, status }; }
  };
}
